Which callbacks compile without a "possibly undefined" error? (Choose two.)

```ts
function f(a: string | undefined) {
  const c = a;
  let l = a;
  let m = a;
  if (c !== undefined && l !== undefined && m !== undefined) {
    [1].forEach(() => c.length); // callback 1
    [1].forEach(() => l.length); // callback 2
    [1].forEach(() => m.length); // callback 3
  }
  m = undefined;
}
```

